const schema = {"type":"object","required":["manifestVersion","bundle","bundle.mediaType","bundle.digest","bundle.url","deployments"],"properties":{"manifestVersion":{"type":"number","description":"Monotonically increasing unsigned 64-bit integer in the inclusive range [1, 2^64-1]. Prevents rollback attacks. The first manifest MUST use 1.\n"},"bundle":{"type":["object","null"],"description":"Describes a single archive containing all ApplicationDeployment documents. If there are zero deployments (deployments array is empty) the property MUST be present with the value null (it MUST NOT be omitted).\n","properties":{"mediaType":{"type":"string","description":"MUST be application/vnd.margo.bundle.v1+tar+gzip; a gzip-compressed tar whose root contains one or more ApplicationDeployment YAML files. If there are zero deployments then bundle MUST be null (an empty archive MUST NOT be served). The archive MUST contain exactly the set of YAML files referenced by deployments.\n"},"digest":{"type":"string","description":"The digest of the bundle archive. MUST equal the digest computed over the exact sequence of bytes (per Exact Bytes Rule) in the bundle endpoint's HTTP 200 OK response body.\n"},"sizeBytes":{"type":"number","description":"Unsigned 64-bit advisory estimate of the decoded payload length in bytes for the bundle archive. Provided for bandwidth estimation and update planning. MUST NOT be used for integrity; digest verification remains mandatory.\n"},"url":{"type":"string","description":"Content-addressable retrieval endpoint of the form /api/v1/clients/{clientId}/bundles/{digest} where {digest} equals bundle.digest.\n"}}},"deployments":{"type":"array","description":"A list of deployment object references for the device. The reference contains some meta info and reference to the url where the deployment is available.","items":{"type":"object","description":"Reference to a deployment manifest with content addressing and integrity verification.\n","required":["deploymentId","digest","url"],"properties":{"deploymentId":{"type":"string","description":"The unique UUID from the ApplicationDeployment's metadata.annotations.id.\n"},"digest":{"type":"string","description":"The digest of the individual ApplicationDeployment YAML file. MUST equal the digest computed over the exact sequence of bytes (per Exact Bytes Rule) in that deployment endpoint's HTTP 200 OK response body.\n"},"sizeBytes":{"type":"number","description":"Unsigned 64-bit advisory estimate of the decoded payload length in bytes for the deployment YAML. Provided for planning or progress display. MUST NOT be used for integrity; digest verification remains mandatory.\n"},"url":{"type":"string","description":"Content-addressable endpoint of the form /api/v1/clients/{clientId}/deployments/{deploymentId}/{digest}. The {digest} MUST equal deployments[].digest; the referenced resource is immutable\n"}}}}}}

// Validate if response matches JSON schema 
